class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        c = sum(x % 2 for x in nums)
        return [0] * (len(nums) - c) + [1] * c

c.cpp:
class Solution {
public:
    vector<int> transformArray(vector<int>& nums) {
        int c = 0;
        for (int x : nums) c += x % 2;
        vector<int> res(nums.size(), 1);
        fill(res.begin(), res.begin() + (nums.size() - c), 0);
        return res;
    }
};

c.java:
class Solution {
    public int[] transformArray(int[] nums) {
        int c = 0;
        for (int x : nums) c += x % 2;
        int[] res = new int[nums.length];
        java.util.Arrays.fill(res, 0, nums.length - c, 0);
        java.util.Arrays.fill(res, nums.length - c, nums.length, 1);
        return res;
    }
}

